/* Scenario lab - client-side re-implementation of the notebook's model.
 *
 * Every formula here mirrors main.ipynb exactly; scenario-data.json carries the
 * per-carrier inputs and is regenerated by scripts/sync_outputs.sh, so the
 * defaults always reproduce the published tables. Nothing is fetched at
 * runtime beyond that one local file.
 *
 * Material's instant navigation swaps the DOM without a page load, so init runs
 * off document$ where available and falls back to DOMContentLoaded.
 */
(function () {
  "use strict";

  var DATA = null;

  // ---- model (mirrors main.ipynb) ---------------------------------------

  function monthlyBurn(revenue, cogs, shock, v) {
    var r = revenue / 12, c = cogs / 12;
    return c * (1 - v) + c * v * (1 - shock) - r * (1 - shock);
  }

  function breakevenShock(revenue, cogs, v) {
    var r = revenue / 12, c = cogs / 12;
    var contribution = r - c * v;
    if (contribution <= 0) return null;      // already burning before any shock
    return 1 - (c * (1 - v)) / contribution;
  }

  function monthsOfLiquidity(revenue, cogs, cash, shock, v) {
    var burn = monthlyBurn(revenue, cogs, shock, v);
    return burn <= 0 ? Infinity : cash / burn;
  }

  // ---- formatting -------------------------------------------------------

  function fmtMonths(m) {
    if (m === null || m === undefined || Number.isNaN(m)) return "n/a";
    if (!isFinite(m)) return "no burn";
    if (m > DATA.displayCap) return ">" + DATA.displayCap;
    return m.toFixed(1);
  }
  function fmtPct(x, dp) { return x === null ? "n/a" : (x * 100).toFixed(dp === undefined ? 0 : dp) + "%"; }
  function fmtX(x, dp) { return x === null || !isFinite(x) ? "n/a" : x.toFixed(dp === undefined ? 1 : dp) + "x"; }

  function el(id) { return document.getElementById(id); }

  // ---- shared helpers ---------------------------------------------------

  /* Min-max to 0-100, higher = better. Mirrors the notebook's _scale: a metric
     that separates nobody scores everyone 50, and missing data scores 0. */
  function scale(values, direction) {
    var vals = values.map(function (v) {
      if (v === null || v === undefined || Number.isNaN(v)) return null;
      return direction === "lower" ? -v : v;
    });
    var present = vals.filter(function (v) { return v !== null; });
    if (!present.length) return vals.map(function () { return 0; });
    var lo = Math.min.apply(null, present), hi = Math.max.apply(null, present);
    if (hi === lo) return vals.map(function (v) { return v === null ? 0 : 50; });
    return vals.map(function (v) { return v === null ? 0 : ((v - lo) / (hi - lo)) * 100; });
  }

  function bindRange(rangeId, outId, fmt, onInput) {
    var range = el(rangeId), out = el(outId);
    if (!range) return null;
    function update() {
      if (out) out.textContent = fmt(parseFloat(range.value));
      onInput();
    }
    range.addEventListener("input", update);
    return update;
  }

  // =======================================================================
  // 1. Stress lab
  // =======================================================================

  function initStress() {
    if (!el("sl-shock")) return;

    var select = el("sl-carrier");
    var inputs = { revenue: el("sl-revenue"), cogs: el("sl-cogs"), cash: el("sl-cash") };

    DATA.order.forEach(function (t) {
      var o = document.createElement("option");
      o.value = t;
      o.textContent = DATA.carriers[t].name + " (" + t + ")";
      select.appendChild(o);
    });
    var custom = document.createElement("option");
    custom.value = "__custom__";
    custom.textContent = "Custom - enter your own";
    select.appendChild(custom);

    function loadCarrier(t) {
      if (t === "__custom__") return;
      var c = DATA.carriers[t];
      inputs.revenue.value = (c.revenue / 1e9).toFixed(2);
      inputs.cogs.value = (c.cogs / 1e9).toFixed(2);
      inputs.cash.value = (c.cash / 1e9).toFixed(2);
    }

    function read() {
      return {
        revenue: (parseFloat(inputs.revenue.value) || 0) * 1e9,
        cogs: (parseFloat(inputs.cogs.value) || 0) * 1e9,
        cash: (parseFloat(inputs.cash.value) || 0) * 1e9,
        v: parseFloat(el("sl-variable").value) / 100,
        shock: parseFloat(el("sl-shock").value) / 100
      };
    }

    function render() {
      var s = read();
      if (s.revenue <= 0 || s.cogs <= 0) {
        el("sl-results").innerHTML = '<p class="sl-empty">Enter a positive revenue and cost of revenue.</p>';
        return;
      }
      var burn = monthlyBurn(s.revenue, s.cogs, s.shock, s.v);
      var months = monthsOfLiquidity(s.revenue, s.cogs, s.cash, s.shock, s.v);
      var be = breakevenShock(s.revenue, s.cogs, s.v);
      var burning = burn > 0;

      var state = burning
        ? (months <= 6 ? "bad" : months <= 12 ? "warn" : "ok")
        : "ok";

      var burnText = burning ? "€" + (burn / 1e6).toFixed(0) + "m" : "none";
      el("sl-results").innerHTML = [
        tile("Monthly cash burn", burnText,
             burning ? "at this shock, cash only" : "still cash generative", state),
        tile("Months of liquidity", fmtMonths(months),
             burning ? "cash only, no external funding" : "shock too shallow to burn", state),
        tile("Breakeven shock", be === null ? "n/a" : "-" + fmtPct(be),
             "revenue decline absorbed before burning", be !== null && be < 0.30 ? "warn" : "ok"),
        tile("Contribution margin", fmtPct(1 - (s.cogs * s.v) / s.revenue),
             "revenue less variable cost", "neutral")
      ].join("");

      drawCurve(s, be);
      renderPeerRow(s);
    }

    function tile(label, value, note, state) {
      return '<div class="sl-tile sl-' + state + '">' +
             '<div class="sl-tile-label">' + label + "</div>" +
             '<div class="sl-tile-value">' + value + "</div>" +
             '<div class="sl-tile-note">' + note + "</div></div>";
    }

    /* Months-of-liquidity swept across shock depth - the same chart as the
       static stress-test page, redrawn live. Runway is capped so one flat
       curve cannot squash the rest. */
    function drawCurve(s, be) {
      var W = 640, H = 260, PAD = { t: 14, r: 16, b: 34, l: 46 };
      var CAP = DATA.displayCap;
      var pts = [];
      for (var i = 0; i <= 160; i++) {
        var shock = (i / 160) * 0.8;
        var m = monthsOfLiquidity(s.revenue, s.cogs, s.cash, shock, s.v);
        pts.push([shock, isFinite(m) ? Math.min(m, CAP) : null]);
      }
      var x = function (v) { return PAD.l + (v / 0.8) * (W - PAD.l - PAD.r); };
      var y = function (v) { return H - PAD.b - (v / CAP) * (H - PAD.t - PAD.b); };

      var d = "", started = false;
      pts.forEach(function (p) {
        if (p[1] === null) { started = false; return; }
        d += (started ? "L" : "M") + x(p[0]).toFixed(1) + "," + y(p[1]).toFixed(1) + " ";
        started = true;
      });

      var grid = "";
      [0, 12, 24, 36].forEach(function (m) {
        grid += '<line class="sl-grid" x1="' + PAD.l + '" x2="' + (W - PAD.r) +
                '" y1="' + y(m) + '" y2="' + y(m) + '"/>' +
                '<text class="sl-axis" x="' + (PAD.l - 8) + '" y="' + (y(m) + 4) +
                '" text-anchor="end">' + m + "</text>";
      });
      [0, 0.2, 0.4, 0.6, 0.8].forEach(function (sh) {
        grid += '<text class="sl-axis" x="' + x(sh) + '" y="' + (H - PAD.b + 18) +
                '" text-anchor="middle">-' + Math.round(sh * 100) + "%</text>";
      });

      var marker = "";
      if (be !== null && be <= 0.8) {
        marker = '<line class="sl-be" x1="' + x(be) + '" x2="' + x(be) + '" y1="' + PAD.t +
                 '" y2="' + (H - PAD.b) + '"/>' +
                 '<text class="sl-be-label" x="' + (x(be) + 6) + '" y="' + (PAD.t + 12) +
                 '">breakeven -' + Math.round(be * 100) + "%</text>";
      }
      var cur = x(s.shock);
      marker += '<line class="sl-cursor" x1="' + cur + '" x2="' + cur + '" y1="' + PAD.t +
                '" y2="' + (H - PAD.b) + '"/>';

      el("sl-chart").innerHTML =
        '<svg viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="Months of liquidity against revenue shock">' +
        grid + marker + '<path class="sl-line" d="' + d + '"/>' +
        '<text class="sl-axis sl-axis-title" x="' + PAD.l + '" y="' + (PAD.t - 2) + '">months</text>' +
        "</svg>";
    }

    /* Same shock and same cost split, applied to all four published carriers -
       so a custom entry can be read against them directly. */
    function renderPeerRow(s) {
      var rows = DATA.order.map(function (t) {
        var c = DATA.carriers[t];
        var m = monthsOfLiquidity(c.revenue, c.cogs, c.cash, s.shock, s.v);
        var be = breakevenShock(c.revenue, c.cogs, s.v);
        return "<tr><td><span class='sl-dot' style='background:" + c.color + "'></span>" +
               c.name + "</td><td>" + fmtMonths(m) + "</td><td>-" + fmtPct(be) + "</td></tr>";
      }).join("");
      el("sl-peers").innerHTML =
        "<table><thead><tr><th>Carrier</th><th>Months at -" +
        Math.round(s.shock * 100) + "%</th><th>Breakeven</th></tr></thead><tbody>" +
        rows + "</tbody></table>";
    }

    select.addEventListener("change", function () { loadCarrier(select.value); render(); });
    Object.keys(inputs).forEach(function (k) {
      inputs[k].addEventListener("input", function () { select.value = "__custom__"; render(); });
    });
    bindRange("sl-shock", "sl-shock-val", function (v) { return "-" + v + "%"; }, render);
    bindRange("sl-variable", "sl-variable-val", function (v) { return v + "%"; }, render);

    select.value = "LHA.DE";      // the carrier the analysis found fragile
    loadCarrier("LHA.DE");
    render();
  }

  // =======================================================================
  // 2. Weight lab - re-rank the composite live
  // =======================================================================

  function initWeights() {
    if (!el("wl-weights")) return;

    var METRICS = ["Cash Ratio", "Current Ratio", "CCC", "Breakeven shock", "Severe -40%"];
    var LABELS = {
      "Cash Ratio": "Cash ratio", "Current Ratio": "Current ratio", "CCC": "Cash cycle",
      "Breakeven shock": "Breakeven shock", "Severe -40%": "Months at -40%"
    };
    var sliders = {};

    el("wl-weights").innerHTML = METRICS.map(function (m) {
      var w = Math.round(DATA.weights[m] * 100);
      return '<div class="wl-row"><label for="wl-' + slug(m) + '">' + LABELS[m] + "</label>" +
             '<input type="range" id="wl-' + slug(m) + '" min="0" max="60" step="5" value="' + w + '">' +
             '<output id="wl-' + slug(m) + '-val">' + w + "%</output></div>";
    }).join("");

    function slug(m) { return m.toLowerCase().replace(/[^a-z0-9]+/g, "-"); }

    METRICS.forEach(function (m) { sliders[m] = el("wl-" + slug(m)); });

    /* Component scores never change - only the weights do. Scaling once keeps
       the sliders honest: what moves is the weighting, not the underlying. */
    var components = {};
    METRICS.forEach(function (m) {
      var raw = DATA.order.map(function (t) {
        var c = DATA.carriers[t];
        if (m === "Cash Ratio") return c.cashRatio;
        if (m === "Current Ratio") return c.current;
        if (m === "CCC") return c.ccc;
        if (m === "Breakeven shock") return breakevenShock(c.revenue, c.cogs, DATA.variableShare);
        // "no burn" is stored as null; cap it at DISPLAY_CAP as the notebook does
        var s40 = c.severe40 === null ? DATA.displayCap : Math.min(c.severe40, DATA.displayCap);
        return s40;
      });
      components[m] = scale(raw, DATA.directions[m]);
    });

    function render() {
      var total = 0;
      METRICS.forEach(function (m) {
        var v = parseFloat(sliders[m].value);
        el("wl-" + slug(m) + "-val").textContent = v + "%";
        total += v;
      });

      el("wl-total").textContent = total + "%";
      el("wl-total").className = "wl-total " + (total === 100 ? "ok" : "warn");
      el("wl-total-note").textContent = total === 100
        ? "weights sum to 100%"
        : "weights sum to " + total + "% - scores below are normalised";

      if (total === 0) {
        el("wl-results").innerHTML = '<p class="sl-empty">Give at least one metric a non-zero weight.</p>';
        return;
      }

      var scores = DATA.order.map(function (t, i) {
        var s = 0;
        METRICS.forEach(function (m) {
          s += components[m][i] * (parseFloat(sliders[m].value) / total);
        });
        return { ticker: t, name: DATA.carriers[t].name, color: DATA.carriers[t].color, score: s };
      });
      scores.sort(function (a, b) { return b.score - a.score; });

      var max = scores[0].score || 1;
      el("wl-results").innerHTML = scores.map(function (s, i) {
        return '<div class="wl-bar-row"><span class="wl-rank">' + (i + 1) + "</span>" +
               '<span class="wl-name"><span class="sl-dot" style="background:' + s.color + '"></span>' +
               s.name + "</span>" +
               '<span class="wl-bar"><span style="width:' + (s.score / max * 100).toFixed(1) +
               "%;background:" + s.color + '"></span></span>' +
               '<span class="wl-score">' + s.score.toFixed(1) + "</span></div>";
      }).join("");

      var order = scores.map(function (s) { return s.ticker; }).join(" > ");
      var published = "IAG.L > RYAAY > AF.PA > LHA.DE";
      el("wl-order").innerHTML = order === published
        ? "<strong>" + order + "</strong> - same order as the published ranking."
        : "<strong>" + order + "</strong> - differs from the published ranking (" + published + ").";
    }

    METRICS.forEach(function (m) { sliders[m].addEventListener("input", render); });
    el("wl-reset").addEventListener("click", function () {
      METRICS.forEach(function (m) { sliders[m].value = Math.round(DATA.weights[m] * 100); });
      render();
    });
    el("wl-equal").addEventListener("click", function () {
      METRICS.forEach(function (m) { sliders[m].value = 20; });
      render();
    });
    render();
  }

  // =======================================================================
  // 3. Ratio calculator - your own eight line items
  // =======================================================================

  function initRatios() {
    if (!el("rc-revenue")) return;

    var FIELDS = ["receivables", "payables", "inventory", "currentAssets",
                  "currentLiabilities", "cash", "revenue", "cogs"];

    function read() {
      var v = {};
      FIELDS.forEach(function (f) { v[f] = parseFloat(el("rc-" + f.toLowerCase().replace(/[^a-z]/g, "")).value); });
      return v;
    }

    function ratio(num, den, scaleBy) {
      if (!isFinite(num) || !isFinite(den) || den === 0) return null;
      return num / den * (scaleBy || 1);
    }

    function band(value, key, betterHigh) {
      if (value === null) return "";
      var peers = DATA.order.map(function (t) { return DATA.carriers[t][key]; })
                            .filter(function (x) { return x !== null; });
      if (!peers.length) return "";
      var lo = Math.min.apply(null, peers), hi = Math.max.apply(null, peers);
      var cls = betterHigh
        ? (value >= hi ? "ok" : value <= lo ? "bad" : "warn")
        : (value <= lo ? "ok" : value >= hi ? "bad" : "warn");
      var where = value > hi ? "above peer range" : value < lo ? "below peer range" : "within peer range";
      return '<span class="rc-band rc-' + cls + '">' + where +
             " (" + lo.toFixed(2) + "-" + hi.toFixed(2) + ")</span>";
    }

    function render() {
      var v = read();
      var days = parseFloat(el("rc-days").value) || 365;
      var dso = ratio(v.receivables, v.revenue, days);
      var dpo = ratio(v.payables, v.cogs, days);
      var dio = ratio(v.inventory, v.cogs, days);
      var ccc = (dso === null || dpo === null || dio === null) ? null : dso + dio - dpo;
      var cur = ratio(v.currentAssets, v.currentLiabilities);
      var quick = ratio(v.currentAssets - v.inventory, v.currentLiabilities);
      var csh = ratio(v.cash, v.currentLiabilities);

      function row(label, val, dp, key, betterHigh, suffix) {
        return "<tr><td>" + label + "</td><td>" +
               (val === null ? "n/a" : val.toFixed(dp) + (suffix || "")) + "</td><td>" +
               (key ? band(val, key, betterHigh) : "") + "</td></tr>";
      }

      el("rc-results").innerHTML =
        "<table><thead><tr><th>Metric</th><th>Value</th><th>vs peers</th></tr></thead><tbody>" +
        row("DSO", dso, 1, "dso", false, "d") +
        row("DPO", dpo, 1, "dpo", true, "d") +
        row("DIO", dio, 1, "dio", false, "d") +
        row("Cash conversion cycle", ccc, 1, "ccc", false, "d") +
        row("Current ratio", cur, 2, "current", true) +
        row("Quick ratio", quick, 2, "quick", true) +
        row("Cash ratio", csh, 2, "cashRatio", true) +
        "</tbody></table>";
    }

    FIELDS.concat(["days"]).forEach(function (f) {
      var node = el("rc-" + f.toLowerCase().replace(/[^a-z]/g, ""));
      if (node) node.addEventListener("input", render);
    });
    el("rc-load").addEventListener("click", function () {
      // Lufthansa's shape, scaled to a €1bn revenue business, as a worked example
      var c = DATA.carriers["LHA.DE"], k = 1e9 / c.revenue;
      el("rc-revenue").value = (c.revenue * k / 1e6).toFixed(0);
      el("rc-cogs").value = (c.cogs * k / 1e6).toFixed(0);
      el("rc-receivables").value = (c.dso / 365 * c.revenue * k / 1e6).toFixed(0);
      el("rc-payables").value = (c.dpo / 365 * c.cogs * k / 1e6).toFixed(0);
      el("rc-inventory").value = (c.dio / 365 * c.cogs * k / 1e6).toFixed(0);
      el("rc-cash").value = (c.cash * k / 1e6).toFixed(0);
      el("rc-currentliabilities").value = (c.cash * k / 1e6 / c.cashRatio).toFixed(0);
      el("rc-currentassets").value = (c.cash * k / 1e6 / c.cashRatio * c.current).toFixed(0);
      render();
    });
    render();
  }

  // =======================================================================
  // 4. Valuation lab - EV bridge and re-rating
  // =======================================================================

  function initValuation() {
    if (!el("vl-mktcap")) return;

    var select = el("vl-carrier");
    DATA.order.forEach(function (t) {
      if (DATA.carriers[t].ev === null || DATA.carriers[t].ev === undefined) return;
      var o = document.createElement("option");
      o.value = t;
      o.textContent = DATA.carriers[t].name + " (" + t + ")";
      select.appendChild(o);
    });
    var custom = document.createElement("option");
    custom.value = "__custom__";
    custom.textContent = "Custom - enter your own";
    select.appendChild(custom);

    function load(t) {
      if (t === "__custom__") return;
      var c = DATA.carriers[t];
      el("vl-mktcap").value = c.mktcap;
      el("vl-debt").value = c.debt;
      el("vl-minority").value = c.minority;
      el("vl-cash").value = c.bridgeCash;
      el("vl-ebitda").value = c.ebitda === null ? "" : c.ebitda.toFixed(2);
    }

    function render() {
      var mktcap = parseFloat(el("vl-mktcap").value) || 0;
      var debt = parseFloat(el("vl-debt").value) || 0;
      var minority = parseFloat(el("vl-minority").value) || 0;
      var cash = parseFloat(el("vl-cash").value) || 0;
      var ebitda = parseFloat(el("vl-ebitda").value) || 0;
      var target = parseFloat(el("vl-target").value) / 10;

      var ev = mktcap + debt + minority - cash;
      var netDebt = debt - cash;
      var evEbitda = ebitda > 0 ? ev / ebitda : null;
      var ndEbitda = ebitda > 0 ? netDebt / ebitda : null;

      var impliedEv = target * ebitda;
      var impliedEquity = impliedEv - debt - minority + cash;
      var upside = mktcap > 0 && ebitda > 0 ? impliedEquity / mktcap - 1 : null;

      el("vl-bridge").innerHTML =
        "<table><tbody>" +
        "<tr><td>Market cap</td><td>" + mktcap.toFixed(1) + "</td></tr>" +
        "<tr><td>+ Total debt (incl. leases)</td><td>" + debt.toFixed(1) + "</td></tr>" +
        "<tr><td>+ Minority interest</td><td>" + minority.toFixed(1) + "</td></tr>" +
        "<tr><td>− Cash</td><td>" + cash.toFixed(1) + "</td></tr>" +
        '<tr class="vl-total"><td>= Enterprise value</td><td>' + ev.toFixed(1) + "</td></tr>" +
        "</tbody></table>";

      el("vl-results").innerHTML = [
        vtile("EV/EBITDA", fmtX(evEbitda), "at the entered market cap"),
        vtile("Net debt/EBITDA", ndEbitda === null ? "n/a" :
              (ndEbitda < 0 ? "net cash " : "") + fmtX(ndEbitda), "leverage"),
        vtile("Implied equity", ebitda > 0 ? "€" + impliedEquity.toFixed(1) + "bn" : "n/a",
              "at " + target.toFixed(1) + "x EV/EBITDA"),
        vtile("Implied upside", upside === null ? "n/a" :
              (upside >= 0 ? "+" : "") + Math.round(upside * 100) + "%", "vs entered market cap")
      ].join("");
    }

    function vtile(label, value, note) {
      return '<div class="sl-tile sl-neutral"><div class="sl-tile-label">' + label +
             '</div><div class="sl-tile-value">' + value +
             '</div><div class="sl-tile-note">' + note + "</div></div>";
    }

    select.addEventListener("change", function () { load(select.value); render(); });
    ["vl-mktcap", "vl-debt", "vl-minority", "vl-cash", "vl-ebitda"].forEach(function (id) {
      el(id).addEventListener("input", function () { select.value = "__custom__"; render(); });
    });
    bindRange("vl-target", "vl-target-val", function (v) { return (v / 10).toFixed(1) + "x"; }, render);

    select.value = "AF.PA";
    load("AF.PA");
    render();
  }

  // ---- boot -------------------------------------------------------------

  function boot() {
    if (!document.querySelector("[data-scenario-lab]")) return;

    function start() {
      initStress();
      initWeights();
      initRatios();
      initValuation();
    }

    if (DATA) { start(); return; }

    fetch(document.querySelector("[data-scenario-lab]").getAttribute("data-src"))
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.json();
      })
      .then(function (json) { DATA = json; start(); })
      .catch(function (err) {
        var host = document.querySelector("[data-scenario-lab]");
        host.innerHTML = '<p class="sl-empty">Could not load the scenario data (' +
          err.message + "). The tables on the other pages are unaffected.</p>";
      });
  }

  if (typeof window.document$ !== "undefined" && window.document$.subscribe) {
    window.document$.subscribe(boot);          // Material instant navigation
  } else if (document.readyState !== "loading") {
    boot();
  } else {
    document.addEventListener("DOMContentLoaded", boot);
  }
})();
